  const button=n('button','2. Проверить в облегчённой модели','primary');button.type='button';button.disabled=r.ran;button.onclick=()=>{if(prediction.value.trim().length<10){status.textContent='Сначала запишите прогноз и его основание.';return;}const before=NeuroLite.evaluate(module.id,s.base),after=NeuroLite.evaluate(module.id,s.target);if(save({ran:true,before:before.value,after:after.value,base:s.base,target:s.target,metric:s.metric,unit:s.resultUnit})){onRun(s.target);}};
